-- Fonte: Polícia Penal do RS
-- https://policiapenal.rs.gov.br/presidios-e-delegacias-penitenciarias
-- Relação regional conferida em 17/08/2026.

alter table public.tc_estabelecimentos_penais
  add column if not exists tipo text not null default 'casa_prisional';

alter table public.tc_estabelecimentos_penais
  add column if not exists fonte_url text;

on conflict (drpp_id, nome) do update
set municipio = excluded.municipio,
    tipo = excluded.tipo,
    fonte_url = excluded.fonte_url,
    ativo = true;
